class Solution {
public:
    bool isPathCrossing(string path) {
        int x = 0, y = 0;
        unordered_set<long long> visited;
        visited.insert(0);

        for (char c : path) {
            if (c == 'N') {
                y++;
            } else if (c == 'S') {
                y--;
            } else if (c == 'E') {
                x++;
            } else if (c == 'W') {
                x--;
            }

            long long key = (long long)x * 100000 + y;
            if (visited.count(key)) {
                return true;
            }
            visited.insert(key);
        }

        return false;
    }
};
